UPDATE `user`
SET ip_info = JSON_SET(ip_info, '$.createIpDetail', CAST(#{detail} AS JSON))
WHERE id = #{uid}
  AND JSON_UNQUOTE(JSON_EXTRACT(ip_info, '$.createIp')) = #{ip}
  AND NOT (JSON_UNQUOTE(JSON_EXTRACT(ip_info, '$.createIpDetail.ip')) <=> #{ip})

UPDATE `user`
SET ip_info = JSON_SET(ip_info, '$.updateIpDetail', CAST(#{detail} AS JSON))
WHERE id = #{uid}
  AND JSON_UNQUOTE(JSON_EXTRACT(ip_info, '$.updateIp')) = #{ip}
  AND NOT (JSON_UNQUOTE(JSON_EXTRACT(ip_info, '$.updateIpDetail.ip')) <=> #{ip})
